function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    var r = Math.random() * 16 | 0;
    var v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

var mediaData = $("get_whatsapp_media") || {};
var mediaString = mediaData.mediaBuffer || (mediaData.data && mediaData.data.mediaBuffer);
if (!mediaString) {
  throw new Error('Missing mediaBuffer from get_whatsapp_media');
}

var mimeType = mediaData.mimeType || (mediaData.data && mediaData.data.mimeType) || 'image/jpeg';
var fileExtension = mimeType.split('/')[1] || 'jpg';
var employeeId = ($input.body && $input.body.employeeId) || 'unknown-employee';
var folderName = 'customizable-workflows/odometer/' + employeeId;
var fileName = uuidv4() + '.' + fileExtension;
var dataUrl = 'data:' + mimeType + ';base64,' + mediaString;

return { dataUrl: dataUrl, folderName: folderName, fileName: fileName, mimeType: mimeType };

function parseOdometerReading(readingString) {
  if (!readingString) return 0;
  var cleanString = readingString.toString().replace(/[,\s]/g, '');
  var match = cleanString.match(/\d+(\.\d+)?/);
  return match ? parseFloat(match[0]) : 0;
}

// The v1 version of this tool answered with WhatsApp BUTTONS. The step engine's odometer
// workflow deliberately asks for a TYPED reply instead, so the confirm/retake/stop decision is
// made by the step finder from the driver's own words, never a button id. Everything below
// composes the full prompt text here; the tool node sends it as the single {{TEXT}} placeholder
// of a template (odometer_extract_validate__send_prompt) via send_template_message, not a free-text send.
function buildPromptMessage(odometerData, failureReason) {
  if (odometerData) {
    var unitText = (!odometerData.unit || odometerData.unit === 'unknown') ? 'units' : odometerData.unit;
    return '🚗 *Odometer reading detected*\n\n'
      + '📊 *Reading:* ' + odometerData.reading + ' ' + unitText + '\n'
      + '🚙 *Vehicle:* ' + (odometerData.vehicleType || 'unknown') + '\n'
      + '🕒 *Captured:* ' + odometerData.capturedAt + '\n\n'
      + 'Is this correct?\n'
      + 'Reply *CONFIRM* to save it, *RETAKE* to send another photo, or *STOP* to cancel.';
  }
  return '❌ *Could not read the odometer*\n\n'
    + '🔍 ' + failureReason + '\n\n'
    + 'Reply *RETAKE* to send another photo, or *STOP* to cancel.\n'
    + 'You can also just send a clearer photo straight away.';
}

function validateOdometerReading(parsedText) {
  var result = { isValid: true, message: '', odometerData: null };

  if (!parsedText || !parsedText.odometer) {
    result.isValid = false;
    result.message = 'That image does not appear to contain an odometer. Please send a photo of the odometer display.';
    return result;
  }

  var odometer = parsedText.odometer;

  if (odometer.reading === 'NO_ODOMETER') {
    result.isValid = false;
    result.message = 'No odometer display was found in the photo. Please send a clear photo of the odometer.';
    return result;
  }
  if (odometer.reading === 'UNCLEAR') {
    result.isValid = false;
    result.message = 'The reading is not clear enough to read. Please send a clearer photo with better lighting and focus.';
    return result;
  }
  if (!odometer.reading || odometer.reading === '') {
    result.isValid = false;
    result.message = 'No reading could be extracted from the photo. Please send a clear photo of the odometer display.';
    return result;
  }

  var numericReading = parseOdometerReading(odometer.reading);
  if (numericReading === 0 && odometer.reading !== '0' && odometer.reading !== '0.0') {
    result.isValid = false;
    result.message = 'The reading format could not be understood. Please make sure the odometer display is fully visible.';
    return result;
  }
  if (numericReading < 0) {
    result.isValid = false;
    result.message = 'Invalid reading: negative values are not allowed.';
    return result;
  }
  if (numericReading > 999999) {
    result.isValid = false;
    result.message = 'That reading looks unusually high. Please check the display and send a clearer photo.';
    return result;
  }
  if (odometer.confidence === 'low') {
    result.isValid = false;
    result.message = 'The reading could not be extracted confidently. Please send a clearer, well-lit photo of the odometer.';
    return result;
  }

  result.odometerData = {
    reading: String(numericReading),
    rawReading: String(odometer.reading),
    unit: odometer.unit || 'kilometers',
    vehicleType: odometer.vehicle_type || 'unknown',
    displayType: odometer.display_type || 'unknown',
    confidence: odometer.confidence || 'medium',
    notes: odometer.notes || '',
    capturedAt: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })
  };
  return result;
}

var body = $input.body || {};
var phoneNumber = body.phoneNumber;
var source = body.source;
var emptyData = {
  reading: '',
  rawReading: '',
  unit: '',
  vehicleType: '',
  displayType: '',
  confidence: '',
  notes: '',
  capturedAt: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })
};

function respond(isValid, data, reason) {
  var resolved = data || emptyData;
  return {
    isValid: isValid,
    reading: resolved.reading,
    rawReading: resolved.rawReading,
    unit: resolved.unit,
    vehicleType: resolved.vehicleType,
    displayType: resolved.displayType,
    confidence: resolved.confidence,
    notes: resolved.notes,
    capturedAt: resolved.capturedAt,
    failureReason: isValid ? '' : reason,
    phoneNumber: phoneNumber,
    source: source,
    message: buildPromptMessage(isValid ? resolved : null, reason)
  };
}

try {
  var openaiResult = $("call_openai") || {};
  var choices = openaiResult.choices || (openaiResult.data && openaiResult.data.choices);
  var content = (choices && choices.length && choices[0].message && choices[0].message.content) || '';

  if (!content) {
    return respond(false, null, 'The image could not be analysed. Please try again with a clearer photo.');
  }

  var parsedText;
  try {
    parsedText = typeof content === 'string' ? JSON.parse(content) : content;
  } catch (parseError) {
    return respond(false, null, 'The image could not be analysed. Please try again with a clearer photo.');
  }

  var validation = validateOdometerReading(parsedText);
  return respond(validation.isValid, validation.odometerData, validation.message);
} catch (error) {
  return respond(false, null, 'Something went wrong while reading the photo. Please try again.');
}

var validation = $("validate_odometer") || {};
var s3Result = $("upload_to_s3") || {};
var mediaUrl = (s3Result.data && s3Result.data.mediaUrl) || s3Result.mediaUrl || '';

// `success` reports that the tool RAN, not that a reading was found: the odometer workflow
// declares "successMode": "always" on this step, so a photo that could not be read still moves
// the driver on to the confirm/retake/stop question instead of burning the retry ceiling.
// Whether a reading was actually extracted is carried by `isValid`, and odometer_record_reading
// is the step that refuses to record without one.
return {
  success: true,
  stateParams: {
    isValid: validation.isValid === true,
    reading: validation.reading || '',
    unit: validation.unit || '',
    vehicleType: validation.vehicleType || '',
    confidence: validation.confidence || '',
    capturedAt: validation.capturedAt || '',
    mediaUrl: mediaUrl
  },
  isValid: validation.isValid === true,
  reading: validation.reading || '',
  rawReading: validation.rawReading || '',
  unit: validation.unit || '',
  vehicleType: validation.vehicleType || '',
  displayType: validation.displayType || '',
  confidence: validation.confidence || '',
  notes: validation.notes || '',
  capturedAt: validation.capturedAt || '',
  failureReason: validation.failureReason || '',
  mediaUrl: mediaUrl,
  message: validation.message || ''
};
